script:
frappe.realtime.on("dummylist",(data)=>{
    frappe.call({
        method:"app1.app1.doctype.dummy.dummy.create_book",
        args:{
            doc:{
                doctype:"dummy",
                title:data.name1
            }
        }
    });
});

frappe.ui.form.on("Employee", {

    refresh: function(frm) {

        frm.add_custom_button("Start Processing", function() {

            frappe.call({
                method: "app1.api.process_employee",

                args: {
                    employee: frm.doc.name
                },

                callback: function(r) {

                    frappe.msgprint(
                        "Processing completed!"
                    );

                    frm.reload_doc();

                }
            });

        });

    }

});

frappe.ui.form.on('User', {
	refresh(frm) {
	    frm.add_custom_button(
            "Send Welcome Email",
            function() {
                frappe.msgprint("Email Sent!");
            },
            "Actions"
        );
	}
})
